        const bands = []; let on = null; h.forEach(([t, st]) => { if (st === "on" && on === null) on = t; if (st !== "on" && on !== null) { bands.push([on, t]); on = null; } }); if (on !== null) bands.push([on, now]);
        const y = 6 + i * rowH; const tot = bands.reduce((a, [s, e]) => a + (e - s), 0) / 3600000;
